import { ConfigUrl } from '../../../../configs/url'
import { getHeaderUploadFile } from '../../../../helpers/utility'

export const PAYOUT_ACTIONS = {
  GET_OFFLINE_POLICIES_REQUEST: 'GET_OFFLINE_POLICIES_REQUEST',
  GET_OFFLINE_POLICIES: 'GET_OFFLINE_POLICIES',

  GET_FILTER_OFFLINE_POLICIES_REQUEST: 'GET_FILTER_OFFLINE_POLICIES_REQUEST',
  GET_FILTER_OFFLINE_POLICIES: 'GET_FILTER_OFFLINE_POLICIES',

  GET_PROOF_SETTLEMENT_REQUEST: 'GET_PROOF_SETTLEMENT_REQUEST',
  GET_PROOF_SETTLEMENT: 'GET_PROOF_SETTLEMENT',

  UPLOAD_PROOF_PHOTO_REQUEST: 'UPLOAD_PROOF_PHOTO_REQUEST',
  UPLOAD_PROOF_PHOTO: 'UPLOAD_PROOF_PHOTO',

  SUBMIT_PROOF_REQUEST: 'SUBMIT_PROOF_REQUEST',
  SUBMIT_PROOF: 'SUBMIT_PROOF',

  GET_PROOF_REQUEST: 'GET_PROOF_REQUEST',
  GET_PROOF: 'GET_PROOF',

  TOGGLE_BONUS_BALANCE: 'TOGGLE_BONUS_BALANCE',

  SUBMIT_PROOF_SETTLEMENT_REQUEST: 'SUBMIT_PROOF_SETTLEMENT_REQUEST',
  SUBMIT_PROOF_SETTLEMENT: 'SUBMIT_PROOF_SETTLEMENT',

  INSTANT_PAYOUT_BALANCE_REQUEST: 'INSTANT_PAYOUT_BALANCE_REQUEST',
  INSTANT_PAYOUT_BALANCE: 'INSTANT_PAYOUT_BALANCE',

  SELECTED_POLICIES_TOTAL_BILL: 'SELECTED_POLICIES_TOTAL_BILL',
  REMOVE_PHOTO_PROOF: 'REMOVE_PHOTO_PROOF',
  UPDATE_POLICIES_ADDITIONAL_INFO: 'UPDATE_POLICIES_ADDITIONAL_INFO',
  SET_POLICIES_AMOUNT: 'SET_POLICIES_AMOUNT',
  RESET_INSTANT_PAYOUT_STATE: 'RESET_INSTANT_PAYOUT_STATE'
}

// if your are calling an api
// you need to pass the data like this
export const getOfflinePolicies = (payload) => ({
  type: PAYOUT_ACTIONS.GET_OFFLINE_POLICIES_REQUEST,
  payload: {
    ...payload,
    method: 'GET',
    url: ConfigUrl.getProofListApi
  }
})

export const getFilterOfflinePolicies = (payload) => ({
  type: PAYOUT_ACTIONS.GET_FILTER_OFFLINE_POLICIES,
  payload: {
    ...payload,
    method: 'GET',
    url: ConfigUrl.getFilterProofListApi
  }
})

export const getProofSettlement = (payload) => ({
  type: PAYOUT_ACTIONS.GET_PROOF_SETTLEMENT_REQUEST,
  payload: {
    ...payload,
    method: 'GET',
    url: ConfigUrl.getProofSettlementApi(payload.proofId),
    query: payload.query
  }
})

export const getProof = (payload) => ({
  type: PAYOUT_ACTIONS.GET_PROOF_REQUEST,
  payload: {
    ...payload,
    method: 'GET',
    url: ConfigUrl.getProofApi(payload.proofId)
  }
})

export const submitProofSettlement = (payload) => ({
  type: PAYOUT_ACTIONS.SUBMIT_PROOF_SETTLEMENT_REQUEST,
  payload: {
    ...payload,
    method: 'POST',
    url: ConfigUrl.submitProofSettlementApi(payload.proofId)
  }
})

export const getTotalBillForSelectedPolicies = (payload) => ({
  type: PAYOUT_ACTIONS.SELECTED_POLICIES_TOTAL_BILL,
  payload
})

export const toggleBonusBalance = (payload) => ({
  type: PAYOUT_ACTIONS.TOGGLE_BONUS_BALANCE,
  payload
})

export const uploadProofPhoto = (payload) => ({
  type: PAYOUT_ACTIONS.UPLOAD_PROOF_PHOTO_REQUEST,
  payload: {
    ...payload,
    headers: getHeaderUploadFile(),
    method: 'POST',
    url: ConfigUrl.getUploadLink
  }
})

export const submitProofPhoto = (payload) => ({
  type: PAYOUT_ACTIONS.SUBMIT_PROOF_REQUEST,
  payload: {
    ...payload,
    method: 'POST',
    url: ConfigUrl.proofSubmitApi
  }
})

export const getInstantPayoutBalance = (payload) => ({
  type: PAYOUT_ACTIONS.INSTANT_PAYOUT_BALANCE_REQUEST,
  payload: {
    ...payload,
    method: 'GET',
    url: ConfigUrl.instantPayoutBalanceApi
  }
})

export const removePhotoProof = (payload) => ({
  type: PAYOUT_ACTIONS.REMOVE_PHOTO_PROOF,
  payload
})

export const updateAdditionalInfo = (payload) => ({
  type: PAYOUT_ACTIONS.UPDATE_POLICIES_ADDITIONAL_INFO,
  payload
})

export const updatePoliciesAmount = (payload) => ({
  type: PAYOUT_ACTIONS.SET_POLICIES_AMOUNT,
  payload
})

export const resetInstantPayout = (payload) => ({
  type: PAYOUT_ACTIONS.RESET_INSTANT_PAYOUT_STATE,
  payload
})
