import { useCallback, useEffect } from 'react'
import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useInstantStateValue } from '../../context'
import {
  getOfflinePolicies, getTotalBillForSelectedPolicies,
  resetInstantPayout, uploadProofPhoto, removePhotoProof,
  submitProofPhoto, submitProofSettlement, updateAdditionalInfo,
  updatePoliciesAmount, getInstantPayoutBalance, getProofSettlement,
  getProof, toggleBonusBalance, getFilterOfflinePolicies
} from '../actions'

export const useGetProofSettlement = () => {
  const [instantPayoutState, dispatch] = useInstantStateValue()
  //  follow this
  const [callApi] = useServiceRequest(dispatch)
  const request = async (payload = {}) => {
    await callApi(getProofSettlement(payload))
  }
  return [instantPayoutState, request]
}

