export const useGetTotalBill = (initial = 0) => {
  const [instantPayoutState, dispatch] = useInstantStateValue()

  const updateTotalBill = useCallback((amount = initial) => {
    dispatch(getTotalBillForSelectedPolicies(amount))
  }, [dispatch, initial])

  useEffect(() => {
    if (initial) {
      updateTotalBill(instantPayoutState.totalBill + initial)
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  return [instantPayoutState.totalBill, updateTotalBill]
}

export const useToggleBonusBalance = () => {
  const [instantPayoutState, dispatch] = useInstantStateValue()

  const changeBonusBalance = useCallback((scenario) => {
    dispatch(toggleBonusBalance(scenario))
  }, [dispatch])

  return [instantPayoutState, changeBonusBalance]
}

