import { get } from 'lodash'
import { PAYOUT_ACTIONS } from './actions'

export const INITIAL_STATE = {
  totalBill: 0,
  policiesAmount: '',
  getOfflinePoliciesMetaData: {},
  getOfflinePoliciesData: [],
  getOfflinePoliciesStatus: '',
  additionalPoliciesInfo: {},
  getProofSettlementData: {}
}

const reducer = (state = INITIAL_STATE, action) => {
  const { type, payload = {} } = action
  switch (type) {
    case PAYOUT_ACTIONS.SUBMIT_PROOF:
    case PAYOUT_ACTIONS.SUBMIT_PROOF_SETTLEMENT:
    case PAYOUT_ACTIONS.INSTANT_PAYOUT_BALANCE:
      return {
        ...state,
        ...payload
      }
    case PAYOUT_ACTIONS.GET_OFFLINE_POLICIES:
      return {
        ...state,
        getOfflinePoliciesData: [
          ...(state.getOfflinePoliciesData || []),
          ...get(payload, 'getOfflinePoliciesData.data', [])
        ],
        getOfflinePoliciesStatus: get(payload, 'getOfflinePoliciesStatus', ''),
        getOfflinePoliciesMetaData: get(
          payload,
          'getOfflinePoliciesData.meta_data',
          {}
        )
      }
    case PAYOUT_ACTIONS.GET_FILTER_OFFLINE_POLICIES:
      return {
        ...state,
        getFilterOfflinePoliciesData: [
          ...get(payload, 'getFilterOfflinePoliciesData.data', [])
        ],
        getFilterOfflinePoliciesStatus: get(payload, 'getFilterOfflinePoliciesStatus', ''),
        getFilterOfflinePoliciesMetaData: get(
          payload,
          'getFilterOfflinePoliciesData.meta_data',
          {}
        )
      }
    case PAYOUT_ACTIONS.GET_PROOF_SETTLEMENT:
      return {
        ...state,
        ...payload
      }
    case PAYOUT_ACTIONS.TOGGLE_BONUS_BALANCE: {
      let getProofSettlementData = {}
      if (!payload) {
        const {
          total_premium: totalPremium,
          offline_amount_payed: offlineAmountPayed
        } = state.getProofSettlementData

        getProofSettlementData = {
          ...state.getProofSettlementData,
          total_tax: 0,
          remaining_payment: totalPremium - offlineAmountPayed
        }
      }
      return {
        ...state,
        ...payload,
        getProofSettlementData
      }
    }
    case PAYOUT_ACTIONS.GET_PROOF:
      return {
        ...state,
        ...payload,
        uploadProofPhotoData: [
          ...(state.uploadProofPhotoData || []),
          ...get(payload, 'getProofData.doc_urls', []).map((obj) => obj.url)
        ]
      }
    case PAYOUT_ACTIONS.UPLOAD_PROOF_PHOTO:
      return {
        ...state,
        uploadProofPhotoData: [
          ...(state.uploadProofPhotoData || []),
          get(payload, 'uploadProofPhotoData.url', '')
        ],
        uploadProofPhotoStatus: action.uploadProofPhotoStatus
      }
    case PAYOUT_ACTIONS.REMOVE_PHOTO_PROOF:
      state.uploadProofPhotoData.splice(payload, 1)
      return {
        ...state
      }
    case PAYOUT_ACTIONS.SELECTED_POLICIES_TOTAL_BILL:
      return {
        ...state,
        totalBill: payload
      }
    case PAYOUT_ACTIONS.UPDATE_POLICIES_ADDITIONAL_INFO:
      return {
        ...state,
        additionalPoliciesInfo: {
          ...(state.additionalPoliciesInfo || {}),
          ...payload
        }
      }
    case PAYOUT_ACTIONS.SET_POLICIES_AMOUNT:
      return {
        ...state,
        policiesAmount: payload
      }
    case PAYOUT_ACTIONS.RESET_INSTANT_PAYOUT_STATE: {
      const modifyStore = {}
      payload.forEach((stateName) => {
        modifyStore[stateName] = ''
      })

      return {
        ...state,
        ...modifyStore
      }
    }
    default:
      return state
  }
}

export default reducer
