import { Container, CustomText } from '../../../../../../components'
import { LANG_STRINGS } from '../../../../../../lang'
import { UnderPaymentStyle } from './index.style'
import { Row } from '../../../../../../commonStyle/index.style'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import { formatMoney } from '../../../../../../helpers/utility'
import ButtonWithIcon from '../../../../../../components/ButtonWithIcon'
import { EMAIL, PASAR_MITRA_NEW, WHATSAPP, TELEPHONE_BLACK, CHECK_GOLD } from '../../../../../../images'
import { useCallback, useEffect, useMemo, useState } from 'react'
import get from 'lodash/get'
import { useErrorContextValue, useLoaderContextValue, resetError } from '@pasarpolis/common-react-hooks'
import { useGetProofSettlement, useSubmitProofSettlement } from '../../../state/hooks/useInstantPayout'
import { NotificationManager, NotificationContainer } from 'react-notifications'
import UnauthorizedAccess from '../../../components/UnauthoriseAccess'

function NotificationUnderPayment (props) {
  const { history } = props
  const [settlementStatus, setSettlementStatus] = useState('')
  const [{
    GET_PROOF_SETTLEMENT_LOADER, SUBMIT_PROOF_SETTLEMENT_LOADER
  }] = useLoaderContextValue()
  const [
    {
      GET_PROOF_SETTLEMENT_ERROR, getProofSettlementStatus,
      SUBMIT_PROOF_SETTLEMENT_ERROR, submitProofSettlementStatus
    },
    dispatchError
  ] = useErrorContextValue()
  const [{ getProofSettlementData = {} }, getProofSettlementRequest] = useGetProofSettlement()
  const [, submitProofSettlementRequest] = useSubmitProofSettlement()
  const proofId = useMemo(() => {
    return get(props, 'match.params.proofId', '')
  }, [props])

  const handleApproveDifference = useCallback(() => {
    submitProofSettlementRequest({
      proofId: proofId,
      body: {
        ...getProofSettlementData
      }
    })
  }, [proofId, submitProofSettlementRequest,
    getProofSettlementData
  ])

  useEffect(() => {
    if (submitProofSettlementStatus === 'success') {
      history.replace({
        pathname: '/instant/payout/confirmation'
      })
      dispatchError(resetError({
        submitProofSettlementStatus: ''
      }))
    } else if (SUBMIT_PROOF_SETTLEMENT_ERROR && submitProofSettlementStatus) {
      NotificationManager.error(submitProofSettlementStatus)
      dispatchError(resetError({
        submitProofSettlementStatus: ''
      }))
    }
  }, [submitProofSettlementStatus, SUBMIT_PROOF_SETTLEMENT_ERROR,
    dispatchError, history
  ])

  useEffect(() => {
    if (GET_PROOF_SETTLEMENT_LOADER === undefined) {
      getProofSettlementRequest({ proofId })
    }
  }, [getProofSettlementRequest, proofId,
    GET_PROOF_SETTLEMENT_LOADER
  ])

  useEffect(() => {
    if (GET_PROOF_SETTLEMENT_ERROR && getProofSettlementStatus && getProofSettlementStatus !== 'success') {
      NotificationManager.error(getProofSettlementStatus)
      dispatchError(resetError({
        getProofSettlementStatus: ''
      }))
      setSettlementStatus(getProofSettlementStatus)
    }
  }, [GET_PROOF_SETTLEMENT_ERROR, getProofSettlementStatus,
    dispatchError
  ])

  const handleOnClose = useCallback(() => {
    history.replace('/dashboard')
  }, [history])

  const renderSection1 = useCallback(() => {
    const {
      total_premium: totalPremium
    } = getProofSettlementData
    return (
      <div className='section margin-bottom-5'>
        <CustomText
          fontSize='18px'
          color={AgentColorPallette.regular}
          weight={900}
        >
          {LANG_STRINGS.differenceToBePaid}
        </CustomText>
        <CustomText
          fontSize='13px'
          color={AgentColorPallette.regular}
          top='8px'
          bottom='12px'
        >
          {LANG_STRINGS.paymentProofDescription}
        </CustomText>

        <Row
          justify='space-between'
        >
          <CustomText
            fontSize='15px'
            color={AgentColorPallette.regular}
            weight={700}
          >
            {LANG_STRINGS.amountToBePaid}
          </CustomText>
          <CustomText
            fontSize='15px'
            color={AgentColorPallette.regular}
            weight={700}
          >
            {formatMoney(totalPremium)}
          </CustomText>
        </Row>
      </div>
    )
  }, [getProofSettlementData])

  const amountRow = useCallback((label, labelDesc, amount) => {
    return (
      <Row justify='space-between' className='amount-row'>
        <div>
          <CustomText
            fontSize='13px'
            color={AgentColorPallette.regular}
          >
            {label}
          </CustomText>
          {
            labelDesc &&
              <CustomText
                fontSize='10px'
                color={AgentColorPallette.fontDarkerGrey}
              >
                {labelDesc}
              </CustomText>
          }
        </div>
        <CustomText
          fontSize='13px'
          color={AgentColorPallette.regular}
        >
          {formatMoney(amount)}
        </CustomText>
      </Row>
    )
  }, [])

  const renderSection2 = useCallback(() => {
    const {
      offline_amount_payed: offlineAmountPayed,
      policy_commission_used: policyCommissionUsed, commission_used: commissionUsed,
      points_used: pointsUsed, payment_by: paymentBy,
      payment_for: paymentFor
    } = getProofSettlementData

    const isPaymentByCustomer = (paymentBy === 'CUSTOMER')

    const isEndorsement = (paymentFor === 'FOR_ENDORSEMENT')

    return (
      <div className='section margin-bottom-5'>
        <CustomText
          fontSize='15px'
          color={AgentColorPallette.regular}
          weight={700}
          className='border-bottom'
        >
          {LANG_STRINGS.payment}
        </CustomText>

        <div className={((commissionUsed > 0) || (policyCommissionUsed > 0)) && 'border-bottom'}>
          <CustomText
            fontSize='13px'
            color={AgentColorPallette.regular}
            weight={800}
          >
            {LANG_STRINGS.offline}
          </CustomText>
          <CustomText
            fontSize='10px'
            color={AgentColorPallette.fontDarkerGrey}
          >
            {LANG_STRINGS.usingPaymentProof}
          </CustomText>
          {
            amountRow(
              LANG_STRINGS.paymentAmount,
              '',
              -offlineAmountPayed
            )
          }
        </div>

        {(isPaymentByCustomer || isEndorsement) &&
          <div className={(commissionUsed > 0 || pointsUsed > 0) && 'border-bottom'}>
            <CustomText
              fontSize='13px'
              color={AgentColorPallette.regular}
              weight={800}
            >
              {LANG_STRINGS.useBonus}
            </CustomText>
            {
              amountRow(
                LANG_STRINGS.bonusUsed,
                '',
                -policyCommissionUsed
              )
            }
          </div>}

        {
          (commissionUsed > 0 || pointsUsed > 0) &&
            <div>
              <CustomText
                fontSize='13px'
                color={AgentColorPallette.regular}
                weight={800}
              >
                {LANG_STRINGS.useBalance}
              </CustomText>
              {
                commissionUsed > 0 &&
                amountRow(
                  LANG_STRINGS.commissionUsed,
                  '',
                  -commissionUsed
                )
              }
              {
                pointsUsed > 0 &&
                amountRow(
                  LANG_STRINGS.pointsUsed,
                  '',
                  -pointsUsed
                )
              }
            </div>
        }

      </div>
    )
  }, [amountRow, getProofSettlementData
  ])

  const renderSection3 = useCallback(() => {
    const {
      remaining_payment: remainingPayment, total_tax: totalTax
    } = getProofSettlementData
    return (
      <div className='section'>
        <div className='border-bottom'>
          {
            amountRow(
              LANG_STRINGS.incomeTax,
              LANG_STRINGS.takenFromBunus,
              totalTax
            )
          }
        </div>
        <Row justify='space-between'>
          <CustomText
            fontSize='15px'
            weight={800}
            color={(remainingPayment === 0) ? AgentColorPallette.regular : AgentColorPallette.maroonRed}
          >
            {LANG_STRINGS.finalDifference}
          </CustomText>
          <CustomText
            fontSize='15px'
            weight={800}
            color={(remainingPayment === 0) ? AgentColorPallette.regular : AgentColorPallette.maroonRed}
          >
            {formatMoney((remainingPayment < 0) ? -remainingPayment : remainingPayment)}
          </CustomText>
        </Row>
        {
          (remainingPayment === 0) &&
            <ButtonWithIcon
              icon={CHECK_GOLD}
              className='approve-btn'
              onClick={handleApproveDifference}
              iconRight
              text={LANG_STRINGS.approveDifferencePayment}
            />
        }
        <CustomText
          fontSize='13px'
          color={AgentColorPallette.regular}
          top='10px'
        >
          <p>{LANG_STRINGS.needHelpCustomerCare}</p>
          <p> {LANG_STRINGS.warmRegards}, </p>
          <img src={PASAR_MITRA_NEW} alt='PP logo' />
        </CustomText>
      </div>
    )
  }, [amountRow, getProofSettlementData, handleApproveDifference])

  const renderSection4 = useCallback(() => {
    return (
      <div>
        <Row className='contact-text'>
          <img alt='phone' height='24px' width='24px' src={TELEPHONE_BLACK} /> &nbsp;&nbsp;
          <CustomText
            fontSize='13px'
            color={AgentColorPallette.regular}
            weight={700}
          >
            {LANG_STRINGS.customerSupportPhone}
          </CustomText>
        </Row>
        <Row className='contact-text'>
          <img alt='whatsapp' height='24px' width='24px' src={WHATSAPP} />&nbsp;&nbsp;
          <CustomText
            fontSize='13px'
            color={AgentColorPallette.regular}
            weight={700}
          >
            {LANG_STRINGS.customerSupportWhatsapp}
          </CustomText>
        </Row>
        <Row className='contact-text'>
          <img alt='email' height='24px' width='24px' src={EMAIL} />&nbsp;&nbsp;
          <CustomText
            fontSize='13px'
            color={AgentColorPallette.regular}
            weight={700}
          >
            {LANG_STRINGS.customerSupportMail}
          </CustomText>
        </Row>
      </div>
    )
  }, [])

  return (
    <Container
      hideBottomTabs
      mitraHeader
      bgColor={AgentColorPallette.white}
      className='bg-white'
      closeIcon
      isBorderBtm
      onClose={handleOnClose}
      loader={GET_PROOF_SETTLEMENT_LOADER || SUBMIT_PROOF_SETTLEMENT_LOADER}
    >
      {
        (GET_PROOF_SETTLEMENT_ERROR === false) && (
          <UnderPaymentStyle>
            {renderSection1()}
            {renderSection2()}
            {renderSection3()}
            {renderSection4()}
            <NotificationContainer />
          </UnderPaymentStyle>
        )
      }
      {
        GET_PROOF_SETTLEMENT_ERROR && (settlementStatus === 'Unauthorize Access') && (
          <UnauthorizedAccess history={history} />
        )
      }
    </Container>
  )
}

export default NotificationUnderPayment
